/**
 * Localized anatomical structure names with SYSTEM-AWARE lookup.
 *
 * Each anatomical term in the BodyParts3D atlas belongs to one of 15 systems
 * (skeletal, muscular, arterial, venous, nervous, etc.). Translation dictionaries
 * are SCOPED per system so e.g. "external oblique" resolves to "腹外斜肌" in
 * the muscular system but to a different term if it ever appears in a different
 * system.
 *
 * Lookup priority within the given system:
 *   1. Exact case-insensitive key
 *   2. Normalized key (strips "muscle"/"artery"/"vein"/"bone" suffixes)
 *   3. Original English name unchanged
 *
 * IMPORTANT: medical terminology should be reviewed by a qualified
 * anatomist/translator before clinical or educational publication.
 * AI-generated translations are best-effort.
 */

export type AnatomyLocale = 'en' | 'zh-CN';
export type AnatomySystem =
  | 'skeletal' | 'muscular' | 'cardiac' | 'arterial' | 'venous'
  | 'nervous' | 'digestive' | 'respiratory' | 'urinary' | 'reproductive'
  | 'lymphatic' | 'endocrine' | 'integumentary' | 'connective' | 'sensory';

function normalizeKey(s: string): string {
  return s
    .toLowerCase()
    .replace(/\b(muscles?|arteries|veins?|bones?)\b/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function buildIndex(dict: Record<string, string>) {
  const exact = new Map<string, string>();
  const normalized = new Map<string, string>();
  for (const [k, v] of Object.entries(dict)) {
    exact.set(k.toLowerCase(), v);
    const norm = normalizeKey(k);
    if (!normalized.has(norm)) normalized.set(norm, v);
  }
  return { exact, normalized };
}

