// Convert _ separated keys back to spaces for the final dict
function expandKeys(raw: Record<string, string>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(raw)) {
    out[k.replace(/_/g, ' ')] = v;
  }
  return out;
}

const MUSCULAR = expandKeys(MUSCULAR_RAW);

